Use `pg` (node-postgres) with `Pool`:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT ?? '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 10,                  // max connections
  min: 2,                   // keep alive minimum
  idleTimeoutMillis: 30000, // close idle after 30s
  connectionTimeoutMillis: 5000, // fail fast if can't connect in 5s

  // Optional: SSL in prod
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
});

// Catch idle errors (e.g. DB restart drops connection)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});
```

**Query helper with automatic release:**

```javascript
export async function query(text, params) {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    return result;
  } catch (err) {
    // Classify and rethrow with context
    if (err.code === '57014') throw new Error('Query timeout');
    if (err.code === 'ECONNREFUSED') throw new Error('DB unreachable');
    throw err;
  } finally {
    // Log slow queries
    const duration = Date.now() - start;
    if (duration > 1000) console.warn('Slow query:', { text, duration });
  }
}
```

**Transaction helper:**

```javascript
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // always release, even on error
  }
}
```

**Graceful shutdown:**

```javascript
process.on('SIGTERM', async () => {
  await pool.end(); // waits for active queries to finish
  process.exit(0);
});
```

Key points:
- `client.release()` in `finally` — leak prevention
- `pool.on('error')` — catches dropped idle connections (DB restart, firewall timeout)
- `connectionTimeoutMillis` — prevents infinite hang on cold start
- `pool.end()` on shutdown — avoids in-flight query corruption
